#[path="split.rs"]mod split;
use serde_json::{json,Value};use std::{collections::BTreeMap,fs};use zopro_bn254::Fr;
const R:&str="/home/ubuntu/src/zopro-perf-work/cross-component-alias176";
type Word=[u64;4];type Token=[u64;2];
const LAMBDA:Fr=Fr::from_decimal("4407920970296243842393367215006156084916469457145843978461");
fn component(s:Word,c:usize)->(u128,bool){(s[2*c]as u128|(((s[2*c+1]&0x7fffffffffffffff)as u128)<<64),s[2*c+1]>>63!=0)}
fn normalized(w:Word)->(Word,bool){let v=Fr::from_canonical(w).unwrap();let neg=(-v).to_canonical();if neg.iter().rev().cmp(w.iter().rev()).is_lt(){(neg,true)}else{(w,false)}}
fn checked_split(w:Word)->Word{let s=split::phi_split(w);let val=|c|{let(m,neg)=component(s,c);let x=Fr::from_canonical([m as u64,(m>>64)as u64,0,0]).unwrap();if neg{-x}else{x}};assert_eq!(val(0)+LAMBDA*val(1),Fr::from_canonical(w).unwrap());s}
fn add(a:Token,b:Token,p:u64)->Token{std::array::from_fn(|i|(a[i]+b[i])%p)}
fn neg(a:Token,p:u64)->Token{a.map(|v|(p-v)%p)}
fn phi(a:Token,p:u64)->Token{[a[1],(p-(a[0]+a[1])%p)%p]}
fn signed(a:Token,n:bool,p:u64)->Token{if n{neg(a,p)}else{a}}
fn scale(a:Token,d:i16,p:u64)->Token{signed(a.map(|v|v*d.unsigned_abs()as u64%p),d<0,p)}
fn digits(m:u128)->[i16;11]{let words=[m as u64,(m>>64)as u64,0,0];std::array::from_fn(|w|split::booth(&words,w,12))}
#[derive(Default,Debug,Clone,PartialEq,Eq)]struct Counts{nonzero:[usize;2],zero:usize,within_classes:usize,mixed_classes:usize,eligible_classes:usize,eligible_members:usize,within_formation:usize,extra_formation:usize,removed:usize,net:usize,one_window_mixed:usize,phi_maps:usize,windows:BTreeMap<(usize,usize,usize),usize>,baseline_arrivals:usize,candidate_arrivals:usize,verified_buckets:usize}
impl Counts{fn value(&self)->Value{json!({"nonzero_component_records":self.nonzero,"zero_components":self.zero,"within_component_duplicate_classes":self.within_classes,"mixed_magnitude_classes":self.mixed_classes,"eligible_mixed_classes":self.eligible_classes,"eligible_mixed_members":self.eligible_members,"comparator_within_formation_adds":self.within_formation,"extra_cross_formation_adds":self.extra_formation,"avoided_cross_bucket_arrivals":self.removed,"net_additional_generic_additions_saved":self.net,"single_window_mixed_classes_skipped":self.one_window_mixed,"additional_phi_maps":self.phi_maps,"additional_phi_Fq_multiplications":self.phi_maps*2,"class_histogram_low_high_windows_classes":self.windows.iter().map(|(&(l,h,w),&n)|vec![l,h,w,n]).collect::<Vec<_>>(),"comparator_bucket_arrivals":self.baseline_arrivals,"candidate_bucket_arrivals":self.candidate_arrivals,"verified_bucket_keys":self.verified_buckets})}}
fn analyze(rows:&[(Word,Token)],p:u64)->Counts{
let mut count=Counts::default();let mut classes=BTreeMap::<u128,[Vec<Token>;2]>::new();for&(s,t)in rows{for c in 0..2{let(m,n)=component(s,c);if m==0{count.zero+=1;continue;}count.nonzero[c]+=1;let token=if c==0{t}else{phi(t,p)};classes.entry(m).or_default()[c].push(signed(token,n,p));}}
let mut before=BTreeMap::<(usize,u16),Token>::new();let mut after=BTreeMap::<(usize,u16),Token>::new();let mut before_presence=BTreeMap::<(usize,u16),usize>::new();let mut after_presence=BTreeMap::<(usize,u16),usize>::new();
for(m,planes)in classes{let ds=digits(m);let w=ds.iter().filter(|&&d|d!=0).count();let(l,h)=(planes[0].len(),planes[1].len());*count.windows.entry((l,h,w)).or_default()+=1;let mixed=l>0&&h>0;if mixed{count.mixed_classes+=1;if w==1{count.one_window_mixed+=1;}}
let mut control=Vec::new();for v in planes{if v.len()>=2{count.within_classes+=1;}if v.len()>=2&&w>=2{count.within_formation+=v.len()-1;control.push(v.iter().fold([0,0],|s,&t|add(s,t,p)));}else{control.extend(v);}}
let selected=mixed&&w>=2;let candidate=if selected{assert_eq!(control.len(),2);count.eligible_classes+=1;count.eligible_members+=l+h;count.extra_formation+=1;count.removed+=w;count.net+=w-1;count.phi_maps+=1;vec![add(control[0],control[1],p)]}else{control.clone()};
let mut insert=|tokens:&[Token],buckets:&mut BTreeMap<(usize,u16),Token>,presence:&mut BTreeMap<(usize,u16),usize>|{for&t in tokens{for(j,&d)in ds.iter().enumerate(){if d!=0{let key=(j,d.unsigned_abs());let old=*buckets.get(&key).unwrap_or(&[0,0]);buckets.insert(key,add(old,scale(t,d,p),p));*presence.entry(key).or_default()+=1;}}}};
insert(&control,&mut before,&mut before_presence);insert(&candidate,&mut after,&mut after_presence);}
assert_eq!(before,after);assert_eq!(before_presence.keys().collect::<Vec<_>>(),after_presence.keys().collect::<Vec<_>>());count.baseline_arrivals=before_presence.values().sum();count.candidate_arrivals=after_presence.values().sum();count.verified_buckets=before.len();assert_eq!(count.baseline_arrivals-count.candidate_arrivals,count.removed);let pairs=|m:&BTreeMap<(usize,u16),usize>|m.values().map(|&n|n-1).sum::<usize>();assert_eq!(pairs(&before_presence)-pairs(&after_presence),count.removed);assert_eq!(count.removed-count.extra_formation,count.net);count}
fn main(){assert!(!std::path::Path::new(&format!("{R}/analysis.json")).exists());let inputs:Value=serde_json::from_slice(&fs::read(format!("{R}/inputs.json")).unwrap()).unwrap();let mut cases=Vec::new();let mut total_classes=0;let mut primary=None;for(name,input)in inputs.as_object().unwrap(){let b=fs::read(input["file"].as_str().unwrap()).unwrap();assert_eq!(&b[..8],b"B2SCAN01");let n=u64::from_le_bytes(b[8..16].try_into().unwrap())as usize;assert_eq!(b.len(),16+160*n);let words=b[16+128*n..].chunks_exact(32).map(|v|std::array::from_fn(|i|u64::from_le_bytes(v[8*i..8*i+8].try_into().unwrap()))).collect::<Vec<Word>>();let part=n.div_ceil(2);let mut parts=Vec::new();let mut net=0;for start in(0..n).step_by(part){let end=(start+part).min(n);let mut groups=BTreeMap::<Word,Vec<(usize,bool)>>::new();for i in start..end{let identity=b[16+128*i..16+128*(i+1)].iter().all(|&v|v==0);if identity||words[i]==[0;4]{continue;}let(k,n)=normalized(words[i]);groups.entry(k).or_default().push((i,n));}let split_groups=groups.iter().map(|(&w,v)|(checked_split(w),v)).collect::<Vec<_>>();total_classes+=split_groups.len();let mut previous=None;for p in[65537u64,1000000007]{let rows=split_groups.iter().map(|&(s,v)|{let token=v.iter().fold([0,0],|sum,&(i,n)|{let t=[((i as u64+1)*7919+37)%p,((i as u64+1)*104729+101)%p];add(sum,signed(t,n,p),p)});(s,token)}).collect::<Vec<_>>();let c=analyze(&rows,p);if let Some(old)=&previous{assert_eq!(*old,c);}previous=Some(c);}let counts=previous.unwrap();net+=counts.net;parts.push(json!({"start":start,"end":end,"active_original_rows":groups.values().map(|v|v.len()).sum::<usize>(),"signed_full_scalar_classes":groups.len(),"counts":counts.value(),"two_small_prime_phi_modules_agree":true}));}if name=="1x2-B"{primary=Some(net>0);}cases.push(json!({"case":name,"raw_rows":n,"parts":parts,"net_additional_generic_additions_saved":net}));}
let out=json!({"complete":true,"necessary_primary_novelty_gate_passed":primary.unwrap(),"normalized_class_split_reconstructions":total_classes,"width":12,"partitions":2,"comparison":"maximal signed full-scalar contraction, then eligible within-component grouping, then only additional cross-component reuse","cases":cases,"phi_model":"two-dimensional additive module, J(a,b)=(b,-a-b), J^2+J+1=0, not elliptic curve arithmetic","new_proofs":0,"proof_ledger":30708,"new_latency_claim":false,"adopted":false,"goal_achieved":false});fs::write(format!("{R}/analysis.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("{}",serde_json::to_string(&out).unwrap());}
#[cfg(test)]mod tests{use super::*;fn packed(a:i128,b:i128)->Word{let f=|x:i128|x.unsigned_abs()|if x<0{1<<127}else{0};let(a,b)=(f(a),f(b));[a as u64,(a>>64)as u64,b as u64,(b>>64)as u64]}
#[test]fn cross_plane_alias_adds_only_new_reuse(){let rows=vec![(packed(4097,7),[13,17]),(packed(19,-4097),[5,11]),(packed(-4097,29),[3,31])];for p in[65537,1000000007]{let c=analyze(&rows,p);assert_eq!(c.within_classes,1);assert_eq!((c.eligible_classes,c.eligible_members,c.extra_formation,c.removed,c.net,c.phi_maps),(1,3,1,2,1,1));}}
#[test]fn zeros_single_windows_signs_and_cancellation(){for n in[0,1,7,31,1025]{let rows=(0..n).map(|i|(packed(if i%2==0{1}else{-1},if i%3==0{0}else{(1<<80)+4097}),[17+i as u64,65537-17])).collect::<Vec<_>>();let a=analyze(&rows,65537);let b=analyze(&rows,1000000007);assert_eq!(a,b);assert_eq!(a.net,0);}for p in[65537,1000000007]{let c=analyze(&[(packed(4097,-4097),[0,0]),(packed(1,-1),[5,7])],p);assert_eq!(c.net,1);assert_eq!(c.one_window_mixed,1);}}
#[test]fn phi_module_and_changing_cross_bucket_conservation(){let mut seed=191u64;for p in[65537u64,1000000007]{for _ in 0..4096{seed^=seed<<13;seed^=seed>>7;seed^=seed<<17;let a=[seed%p,seed.rotate_left(17)%p];let b=[seed.rotate_left(29)%p,seed.rotate_left(43)%p];assert_eq!(phi(add(a,b,p),p),add(phi(a,p),phi(b,p),p));assert_eq!(add(add(phi(phi(a,p),p),phi(a,p),p),a,p),[0,0]);}for n in[0usize,1,8,33,513]{let rows=(0..n).map(|i|{let m=((i%7)as i128+1)*((1i128<<80)+4097);(packed(if i%2==0{m}else{-m},if i%3==0{-m}else{m+3}),[(i as u64*7919+37)%p,(i as u64*104729+101)%p])}).collect::<Vec<_>>();let c=analyze(&rows,p);assert_eq!(c.net,c.removed-c.extra_formation);}}}
}
